	buildBicycle() {
		const tire = new MeshStandardMaterial({
			color: 2106920,
			roughness: .94
		});
		const metal = new MeshStandardMaterial({
			color: 12108991,
			metalness: .64,
			roughness: .38
		});
		const front = new Vector3(0, .46, -.78);
		const rear = new Vector3(0, .46, .78);
		const crank = new Vector3(0, .54, 0);
		const seat = new Vector3(0, 1.02, .32);
		const handle = new Vector3(0, 1.04, -.58);
		for (const wheelPosition of [front, rear]) {
			const wheel = new Mesh(new TorusGeometry(.43, .055, 6, 18), tire);
			wheel.rotation.y = Math.PI / 2;
			wheel.position.copy(wheelPosition);
			wheel.castShadow = true;
			this.root.add(wheel);
			this.wheels.push(wheel);
			this.addBar(wheelPosition.clone().add(new Vector3(-.03, 0, 0)), wheelPosition.clone().add(new Vector3(.03, 0, 0)), .045, metal);
		}
		this.addBar(rear, crank, .052, this.bodyMaterial);
		this.addBar(crank, seat, .052, this.bodyMaterial);
		this.addBar(seat, rear, .052, this.bodyMaterial);
		this.addBar(front, crank, .052, this.bodyMaterial);
		this.addBar(handle, crank, .052, this.bodyMaterial);
		this.addBar(front, handle, .052, metal);
		this.addBox([
			.42,
			.1,
			.18
		], 1.04, tire, 0, .37);
		this.addBox([
			.72,
			.07,
			.09
		], 1.08, metal, 0, -.62);
		this.addBox([
			.22,
			.12,
			.12
		], .58, metal, 0, 0);
		this.root.add(this.riderGroup);
		const skin = new MeshStandardMaterial({
			color: 14987916,
			roughness: .8
		});
		const shirt = new MeshStandardMaterial({
			color: 15680580,
			roughness: .7
		});
		const pants = new MeshStandardMaterial({
			color: 1920728,
			roughness: .75
		});
		const head = new Mesh(new SphereGeometry(.18, 10, 8), skin);
		head.position.set(0, 1.62, -.1);
		head.castShadow = true;
		this.riderGroup.add(head);
		const seatPos = new Vector3(0, 1.02, .22);
		const neckPos = new Vector3(0, 1.48, -.1);
		this.addRiderBar(seatPos, neckPos, .088, shirt);
		const leftShoulder = new Vector3(.18, 1.42, -.1);
		const rightShoulder = new Vector3(-.18, 1.42, -.1);
		const leftGrip = new Vector3(.36, 1.04, -.58);
		const rightGrip = new Vector3(-.36, 1.04, -.58);
		this.addRiderBar(leftShoulder, leftGrip, .045, shirt);
		this.addRiderBar(rightShoulder, rightGrip, .045, shirt);
		const leftHip = new Vector3(.14, .96, .2);
		const rightHip = new Vector3(-.14, .96, .2);
		const leftPedal = new Vector3(.24, .44, .1);
		const rightPedal = new Vector3(-.24, .64, -.1);
		this.addRiderBar(leftHip, leftPedal, .052, pants);
		this.addRiderBar(rightHip, rightPedal, .052, pants);
	}
	setRiderVisible(visible) {
		if (this.kind === "monster_truck") {
			this.riderGroup.visible = !this.isRobotMode && visible;
			return;
		}
		this.riderGroup.visible = visible;
	}
	toggleRobotMode(force) {
		if (this.kind !== "monster_truck") return false;
		this.isRobotMode = force !== void 0 ? force : !this.isRobotMode;
		this.truckGroup.visible = !this.isRobotMode;
		this.robotGroup.visible = this.isRobotMode;
		return this.isRobotMode;
	}
	getBlasterMuzzleWorldPosition() {
		const pos = new Vector3();
		if (this.robotBlasterMuzzle) {
			this.robotBlasterMuzzle.getWorldPosition(pos);
			return pos;
		}
		pos.set(this.root.position.x, this.root.position.y + 3.8, this.root.position.z);
		return pos;
	}
	getThrusterWorldPositions() {
		return this.robotThrusters.map((th) => {
			const pos = new Vector3();
			th.getWorldPosition(pos);
			return pos;
		});
	}
	updateRobotAnimation(dt) {
		if (this.kind !== "monster_truck" || !this.isRobotMode) return;
		if (this.rocketFlameL && this.rocketFlameR) {
			if (this.isThrusting) {
				this.rocketFlameL.visible = true;
				this.rocketFlameR.visible = true;
				const flamePulse = .9 + Math.sin(this.robotWalkTimer * 28) * .28;
				this.rocketFlameL.scale.set(1.1, flamePulse, 1.1);
				this.rocketFlameR.scale.set(1.1, flamePulse, 1.1);
			} else {
				this.rocketFlameL.visible = false;
				this.rocketFlameR.visible = false;
			}
		}
		if (Math.abs(this.speed) > .4) {
			this.robotWalkTimer += dt * (Math.abs(this.speed) * .4 + 2.5);
			const legAngle = Math.sin(this.robotWalkTimer) * .45;
			if (this.robotLeftLeg) this.robotLeftLeg.rotation.x = legAngle;
			if (this.robotRightLeg) this.robotRightLeg.rotation.x = -legAngle;
			if (this.robotLeftArm) this.robotLeftArm.rotation.x = -legAngle * .8;
			if (this.robotRightArm) this.robotRightArm.rotation.x = -.25 + Math.sin(this.robotWalkTimer * .5) * .06;
		} else {
			this.robotWalkTimer += dt;
			if (this.robotLeftLeg) this.robotLeftLeg.rotation.x *= Math.max(0, 1 - dt * 8);
			if (this.robotRightLeg) this.robotRightLeg.rotation.x *= Math.max(0, 1 - dt * 8);
			if (this.robotLeftArm) this.robotLeftArm.rotation.x = Math.sin(this.robotWalkTimer * 2) * .05;
			if (this.robotRightArm) this.robotRightArm.rotation.x = -.25 + Math.sin(this.robotWalkTimer * 2) * .04;
		}
	}
	addTruckBox(size, y, material, x = 0, z = 0, isDetail = false) {
		const mesh = new Mesh(new BoxGeometry(...size), material);
		mesh.position.set(x, y, z);
		mesh.castShadow = true;
		mesh.receiveShadow = true;
		mesh.userData.boxSize = size;
		if (isDetail) mesh.userData.isDetail = true;
		this.truckGroup.add(mesh);
		return mesh;
	}
	addRobotBox(group, size, pos, material, isDetail = false) {
		const mesh = new Mesh(new BoxGeometry(...size), material);
		mesh.position.set(...pos);
		mesh.castShadow = true;
		mesh.receiveShadow = true;
		mesh.userData.boxSize = size;
		if (isDetail) mesh.userData.isDetail = true;
		group.add(mesh);
		return mesh;
	}
