		const bar = new Mesh(new CylinderGeometry(radius * .72, radius, direction.length(), 6), material);
		bar.position.copy(start).add(end).multiplyScalar(.5);
		bar.quaternion.setFromUnitVectors(new Vector3(0, 1, 0), direction.normalize());
