		const rightA = new Vector2(Math.cos(this.yaw), -Math.sin(this.yaw));
		const forwardA = new Vector2(-Math.sin(this.yaw), -Math.cos(this.yaw));
		const rightB = new Vector2(Math.cos(other.yaw), -Math.sin(other.yaw));
		const forwardB = new Vector2(-Math.sin(other.yaw), -Math.cos(other.yaw));
		const halfWidthA = this.halfWidth * this.scale;
