		const velocityB = new Vector2(-Math.sin(other.yaw) * other.speed + other.driftVelocity.x, -Math.cos(other.yaw) * other.speed + other.driftVelocity.y);
		const closingSpeed = (velocityB.x - velocityA.x) * normalX + (velocityB.y - velocityA.y) * normalZ;
