	buildAirportRunway(group, structuresGroup, centerX, centerZ, bounds, chunkCoins) {
		const deck = new Mesh(new PlaneGeometry(36, 48), this.runwayAsphalt);
		deck.rotation.x = -Math.PI / 2;
		deck.position.set(centerX, .024, centerZ);
		deck.receiveShadow = true;
		group.add(deck);
		for (const side of [-1, 1]) {
			const line = new Mesh(new PlaneGeometry(.5, 48), this.runwayPaintYellow);
			line.rotation.x = -Math.PI / 2;
			line.position.set(centerX + side * 17.2, .026, centerZ);
			group.add(line);
		}
		for (let d = 0; d < 4; d += 1) {
			const dash = new Mesh(new PlaneGeometry(.8, 6), this.runwayPaintWhite);
			dash.rotation.x = -Math.PI / 2;
			dash.position.set(centerX, .026, centerZ - 18 + d * 12);
			group.add(dash);
		}
		const isStart = centerZ <= -120 && centerZ >= -160;
		if (isStart || centerZ >= 200 && centerZ <= 240) {
			for (let s = -6; s <= 6; s += 1) {
				if (s === 0) continue;
				const stripe = new Mesh(new PlaneGeometry(1.6, 9), this.runwayPaintWhite);
				stripe.rotation.x = -Math.PI / 2;
				stripe.position.set(centerX + s * 2.4, .027, centerZ + (isStart ? -14 : 14));
				group.add(stripe);
			}
			for (let s = -7; s <= 7; s += 1) {
				const light = new Mesh(new CylinderGeometry(.18, .22, .45, 8), isStart ? this.runwayLightGreen : this.runwayLightRed);
				light.position.set(centerX + s * 2.3, .24, centerZ + (isStart ? -22 : 22));
				group.add(light);
			}
		}
		for (let side of [-1, 1]) for (let p = -2; p <= 2; p += 1) {
			const light = new Mesh(new CylinderGeometry(.12, .16, .4, 8), this.runwayLightWhite);
			light.position.set(centerX + side * 18.2, .2, centerZ + p * 11);
			group.add(light);
		}
		if (Math.abs(centerZ) < 30) {
			const towerBase = new Mesh(new CylinderGeometry(2.8, 3.6, 18, 12), this.airportBuildingMat);
			towerBase.position.set(centerX + 32, 9, centerZ);
			towerBase.castShadow = true;
			towerBase.receiveShadow = true;
			structuresGroup.add(towerBase);
			const towerDeck = new Mesh(new CylinderGeometry(4.4, 4.4, 3.2, 12), this.houseWindowMaterial);
			towerDeck.position.set(centerX + 32, 19.5, centerZ);
			towerDeck.castShadow = true;
			structuresGroup.add(towerDeck);
			const towerRoof = new Mesh(new ConeGeometry(4.8, 1.8, 12), this.airportRoofMat);
			towerRoof.position.set(centerX + 32, 21.9, centerZ);
			structuresGroup.add(towerRoof);
			bounds.push({
				minX: centerX + 32 - 4.5,
				maxX: centerX + 32 + 4.5,
				minZ: centerZ - 4.5,
				maxZ: centerZ + 4.5,
				minY: 0,
				maxY: 23
			});
		} else if (Math.abs(centerZ - 96) < 30 || Math.abs(centerZ - -96) < 30) {
			const hangar = new Mesh(new BoxGeometry(16, 8.5, 28), this.airportBuildingMat);
			hangar.position.set(centerX + 34, 4.25, centerZ);
			hangar.castShadow = true;
			hangar.receiveShadow = true;
			structuresGroup.add(hangar);
			const hangarRoof = new Mesh(new CylinderGeometry(8.2, 8.2, 28, 14, 1, false, 0, Math.PI), this.airportRoofMat);
			hangarRoof.rotation.z = Math.PI / 2;
			hangarRoof.position.set(centerX + 34, 8.5, centerZ);
			hangarRoof.castShadow = true;
			structuresGroup.add(hangarRoof);
			bounds.push({
				minX: centerX + 34 - 8.5,
				maxX: centerX + 34 + 8.5,
				minZ: centerZ - 14.5,
				maxZ: centerZ + 14.5,
				minY: 0,
				maxY: 17
			});
		}
		const coinMesh = new Mesh(this.coinGeometry, this.coinMaterial);
		coinMesh.rotation.x = Math.PI / 2;
		coinMesh.position.set(centerX, 1.2, centerZ);
		coinMesh.castShadow = true;
		group.add(coinMesh);
		chunkCoins.push({
			mesh: coinMesh,
			x: centerX,
			z: centerZ,
			alive: true
		});
	}
