//#region src/game/FloatingRings.ts
var FloatingRings = class {
	scene;
	root = new Group();
	rings = [];
	torusGeometry = new TorusGeometry(4.8, .42, 14, 32);
	coreGeometry = new TorusGeometry(3.6, .16, 8, 24);
	ringMaterial = new MeshStandardMaterial({
		color: 61695,
		emissive: 54015,
		emissiveIntensity: 1.8,
		roughness: .15,
		metalness: .2
	});
	goldRingMaterial = new MeshStandardMaterial({
		color: 16758531,
		emissive: 16483584,
		emissiveIntensity: 2.2,
		roughness: .15,
		metalness: .3
	});
	collectedMaterial = new MeshStandardMaterial({
		color: 4674921,
		emissive: 1976635,
		emissiveIntensity: .2,
		roughness: .8,
		transparent: true,
		opacity: .35
	});
	constructor(scene) {
		this.scene = scene;
		this.scene.add(this.root);
		this.generateRings();
	}
	generateRings() {
		[
			{
				x: 144,
				y: 16,
				z: -40,
				rotY: 0
			},
			{
				x: 144,
				y: 26,
				z: 30,
				rotY: 0
			},
			{
				x: 144,
				y: 34,
				z: 100,
				rotY: 0
			},
			{
				x: 96,
				y: 38,
				z: 160,
				rotY: Math.PI / 4
			},
			{
				x: 24,
				y: 42,
				z: 180,
				rotY: Math.PI / 2
			},
			{
				x: -48,
				y: 40,
				z: 160,
				rotY: 3 * Math.PI / 4
			},
			{
				x: -96,
				y: 36,
				z: 90,
				rotY: Math.PI
			},
			{
				x: -96,
				y: 30,
				z: 0,
				rotY: Math.PI
			},
			{
				x: -96,
				y: 24,
				z: -80,
				rotY: Math.PI
			},
			{
				x: -144,
				y: 18,
				z: -140,
				rotY: -Math.PI / 4
			},
			{
				x: -48,
				y: 22,
				z: -180,
				rotY: 0
			},
			{
				x: 48,
				y: 30,
				z: -180,
				rotY: Math.PI / 2
			},
			{
				x: 0,
				y: 48,
				z: -100,
				rotY: Math.PI / 3,
				gold: true
			},
			{
				x: 0,
				y: 52,
				z: 0,
				rotY: 0,
				gold: true
			},
			{
				x: 0,
				y: 46,
				z: 100,
				rotY: -Math.PI / 3,
				gold: true
			},
			{
				x: 192,
				y: 28,
				z: 0,
				rotY: Math.PI / 2
			},
			{
				x: 192,
				y: 32,
				z: 120,
				rotY: Math.PI / 4
			},
			{
				x: -192,
				y: 30,
				z: 40,
				rotY: -Math.PI / 3
			},
			{
				x: -192,
				y: 25,
				z: -60,
				rotY: 0
			},
			{
				x: 48,
				y: 35,
				z: 48,
				rotY: Math.PI / 6
			}
		].forEach((wp, index) => {
			const group = new Group();
			group.position.set(wp.x, wp.y, wp.z);
			group.rotation.y = wp.rotY ?? 0;
			const torusMat = wp.gold ? this.goldRingMaterial : this.ringMaterial;
			const torusMesh = new Mesh(this.torusGeometry, torusMat);
			torusMesh.castShadow = false;
			torusMesh.receiveShadow = false;
			group.add(torusMesh);
			const coreMesh = new Mesh(this.coreGeometry, torusMat);
			group.add(coreMesh);
			const beaconGeo = new SphereGeometry(.3, 8, 8);
			const beaconMat = new MeshStandardMaterial({
				color: 16777215,
				emissive: 65535,
				emissiveIntensity: 2.5
			});
			const topBeacon = new Mesh(beaconGeo, beaconMat);
			topBeacon.position.set(0, 4.8, 0);
			group.add(topBeacon);
			const bottomBeacon = new Mesh(beaconGeo, beaconMat);
			bottomBeacon.position.set(0, -4.8, 0);
			group.add(bottomBeacon);
			this.root.add(group);
			this.rings.push({
				id: index + 1,
				position: new Vector3(wp.x, wp.y, wp.z),
				radius: 5.2,
				rotationY: wp.rotY ?? 0,
				mesh: group,
				torusMesh,
				coreMesh,
				collected: false,
				cooldownTimer: 0
			});
		});
	}
	update(dt, planePosition, isPlaneActive, consecutiveCount) {
		let result = null;
		for (const ring of this.rings) {
			ring.mesh.rotation.z += dt * .8;
			ring.coreMesh.rotation.z -= dt * 1.4;
			if (ring.collected) {
				ring.cooldownTimer -= dt;
				if (ring.cooldownTimer <= 0) {
					ring.collected = false;
					ring.torusMesh.material = this.ringMaterial;
					ring.coreMesh.material = this.ringMaterial;
					ring.mesh.scale.set(1, 1, 1);
				}
				continue;
			}
			if (isPlaneActive) {
				if (planePosition.distanceTo(ring.position) <= ring.radius) {
					ring.collected = true;
					ring.cooldownTimer = 18;
					ring.torusMesh.material = this.collectedMaterial;
					ring.coreMesh.material = this.collectedMaterial;
					ring.mesh.scale.set(1.35, 1.35, 1.35);
					const newCount = consecutiveCount + 1;
					const missionCompleted = newCount === 7;
					result = {
						collected: true,
						ringId: ring.id,
						consecutiveCount: newCount,
						missionCompleted,
						position: ring.position.clone(),
						rewardPoints: 200,
						rewardCash: 150
					};
				}
			}
		}
		return result;
	}
	reset() {
		for (const ring of this.rings) {
			ring.collected = false;
			ring.cooldownTimer = 0;
			ring.torusMesh.material = this.ringMaterial;
			ring.coreMesh.material = this.ringMaterial;
			ring.mesh.scale.set(1, 1, 1);
		}
	}
	dispose() {
		this.scene.remove(this.root);
		this.torusGeometry.dispose();
		this.coreGeometry.dispose();
		this.ringMaterial.dispose();
		this.goldRingMaterial.dispose();
		this.collectedMaterial.dispose();
	}
};
