//#region src/game/Helicopter.ts
var Helicopter = class {
	scene;
	root = new Group();
	mainRotor;
	tailRotor;
	maxHits = 25;
	smokeThreshold = 18;
	hits = 0;
	exploded = false;
	hitCooldown = 0;
	smokeTimer = 0;
	fireTimer = 0;
	speed = 0;
	yaw = 0;
	pitch = 0;
	roll = 0;
	altitude = 18;
	bodyMaterial;
	darkMetalMaterial;
	glassMaterial;
	rotorMaterial;
	constructor(scene, startX, startZ, startAltitude = 20) {
		this.scene = scene;
		this.altitude = startAltitude;
		this.bodyMaterial = new MeshStandardMaterial({
			color: 1976888,
			roughness: .55,
			metalness: .35
		});
		this.darkMetalMaterial = new MeshStandardMaterial({
			color: 1382426,
			roughness: .72,
			metalness: .6
		});
		this.glassMaterial = new MeshStandardMaterial({
			color: 8308963,
			roughness: .15,
			metalness: .4,
			transparent: true,
			opacity: .5
		});
		this.rotorMaterial = new MeshStandardMaterial({
			color: 987410,
			roughness: .8,
			metalness: .5
		});
		const heliBody = new Group();
		const cabinGeo = new CylinderGeometry(.9, .7, 4.4, 10);
		cabinGeo.rotateX(Math.PI / 2);
		const cabin = new Mesh(cabinGeo, this.bodyMaterial);
		cabin.position.set(0, 0, 0);
		cabin.castShadow = true;
		cabin.receiveShadow = true;
		heliBody.add(cabin);
		const canopyGeo = new SphereGeometry(.85, 10, 8);
		canopyGeo.scale(.85, .75, 1.4);
		const canopy = new Mesh(canopyGeo, this.glassMaterial);
		canopy.position.set(0, .25, -1.2);
		canopy.castShadow = true;
		heliBody.add(canopy);
		const boom = new Mesh(new ConeGeometry(.35, 4.8, 8), this.bodyMaterial);
		boom.rotateX(-Math.PI / 2);
		boom.position.set(0, .2, 3.6);
		boom.castShadow = true;
		heliBody.add(boom);
		const tailFin = new Mesh(new BoxGeometry(.08, 1.4, .85), this.bodyMaterial);
		tailFin.position.set(0, .6, 5.8);
		tailFin.castShadow = true;
		heliBody.add(tailFin);
		this.mainRotor = new Group();
		this.mainRotor.position.set(0, 1.15, -.2);
		const mast = new Mesh(new CylinderGeometry(.1, .12, .55, 8), this.darkMetalMaterial);
		this.mainRotor.add(mast);
		const bladeGeo = new BoxGeometry(7.2, .04, .32);
		const blade1 = new Mesh(bladeGeo, this.rotorMaterial);
		this.mainRotor.add(blade1);
		const blade2 = new Mesh(bladeGeo, this.rotorMaterial);
		blade2.rotation.y = Math.PI / 2;
		this.mainRotor.add(blade2);
		heliBody.add(this.mainRotor);
		this.tailRotor = new Group();
		this.tailRotor.position.set(.18, .85, 5.9);
		const tailBladeGeo = new BoxGeometry(1.4, .03, .12);
		const tailBlade1 = new Mesh(tailBladeGeo, this.rotorMaterial);
		this.tailRotor.add(tailBlade1);
		const tailBlade2 = new Mesh(tailBladeGeo, this.rotorMaterial);
		tailBlade2.rotation.z = Math.PI / 2;
		this.tailRotor.add(tailBlade2);
		heliBody.add(this.tailRotor);
		const stubWings = new Mesh(new BoxGeometry(3.2, .12, .65), this.bodyMaterial);
		stubWings.position.set(0, -.15, -.4);
		stubWings.castShadow = true;
		heliBody.add(stubWings);
		for (const side of [-1, 1]) {
			const pod = new Mesh(new CylinderGeometry(.24, .24, 1.4, 8), this.darkMetalMaterial);
			pod.rotateX(Math.PI / 2);
			pod.position.set(side * 1.4, -.35, -.4);
			pod.castShadow = true;
			heliBody.add(pod);
		}
		const gun = new Mesh(new CylinderGeometry(.06, .08, .9, 6), this.darkMetalMaterial);
		gun.rotateX(Math.PI / 2);
		gun.position.set(0, -.65, -1.6);
		heliBody.add(gun);
		const skidMat = this.darkMetalMaterial;
		for (const side of [-1, 1]) {
			const skid = new Mesh(new CylinderGeometry(.06, .06, 3.8, 8), skidMat);
			skid.rotateX(Math.PI / 2);
			skid.position.set(side * .9, -1.05, 0);
			skid.castShadow = true;
			heliBody.add(skid);
			for (const z of [-.9, .9]) {
				const strut = new Mesh(new CylinderGeometry(.04, .04, .65, 6), skidMat);
				strut.position.set(side * .75, -.75, z);
				heliBody.add(strut);
			}
		}
		this.root.add(heliBody);
		this.setPosition(startX, startZ, this.altitude);
		this.scene.add(this.root);
	}
	get isSmoking() {
		return this.hits >= this.smokeThreshold && !this.exploded;
	}
	setPosition(x, z, y = 20, yaw = 0) {
		this.yaw = yaw;
		this.altitude = y;
		this.root.position.set(x, y, z);
		this.root.rotation.set(0, yaw, 0);
	}
	getFireOrigin() {
		const p = new Vector3(0, -.5, -1.8);
		p.applyEuler(this.root.rotation);
		p.add(this.root.position);
		return p;
	}
	getEnginePosition() {
		const p = new Vector3(0, .8, .4);
		p.applyEuler(this.root.rotation);
		p.add(this.root.position);
		return p;
	}
	update(dt, targetPosition) {
		if (this.exploded) return {
			readyToFire: false,
			fireOrigin: new Vector3(),
			fireTarget: new Vector3()
		};
		if (this.hitCooldown > 0) this.hitCooldown = Math.max(0, this.hitCooldown - dt);
		this.mainRotor.rotation.y += dt * 26;
		this.tailRotor.rotation.x += dt * 32;
		const dx = targetPosition.x - this.root.position.x;
		const dz = targetPosition.z - this.root.position.z;
		const distToTarget = Math.hypot(dx, dz);
		const desiredYaw = Math.atan2(-dx, -dz);
		const yawDiff = MathUtils.euclideanModulo(desiredYaw - this.yaw + Math.PI, Math.PI * 2) - Math.PI;
		this.yaw += MathUtils.clamp(yawDiff, -dt * 1.5, dt * 1.5);
		this.pitch = MathUtils.lerp(this.pitch, distToTarget > 15 ? .22 : .05, dt * 2);
		this.roll = MathUtils.lerp(this.roll, yawDiff * -.3, dt * 3);
		this.root.rotation.set(this.pitch, this.yaw, this.roll, "YXZ");
		const targetAlt = Math.max(14, targetPosition.y + 12);
		this.altitude = MathUtils.lerp(this.altitude, targetAlt, dt * 1.5);
		const chaseSpeed = distToTarget > 25 ? 32 : 18;
		this.speed = MathUtils.lerp(this.speed, chaseSpeed, dt * 1.8);
		this.root.position.x += -Math.sin(this.yaw) * this.speed * dt;
		this.root.position.z += -Math.cos(this.yaw) * this.speed * dt;
		this.root.position.y = this.altitude;
		this.fireTimer += dt;
		let readyToFire = false;
		const fireOrigin = this.getFireOrigin();
		const fireTarget = targetPosition.clone();
		if (this.fireTimer >= 2.4 && distToTarget > 8 && distToTarget < 110) {
			this.fireTimer = 0;
			readyToFire = true;
		}
		return {
			readyToFire,
			fireOrigin,
			fireTarget
		};
	}
	registerHit(_type = "collision", cooldown = .25) {
		if (this.exploded) return {
			hitRegistered: false,
			isNewExplosion: false,
			hits: this.hits
		};
		if (this.hitCooldown > 0) return {
			hitRegistered: false,
			isNewExplosion: false,
			hits: this.hits
		};
		this.hitCooldown = cooldown;
		this.hits += 1;
		if (this.hits >= this.maxHits) {
			this.exploded = true;
			this.root.visible = false;
			return {
				hitRegistered: true,
				isNewExplosion: true,
				hits: this.hits
			};
		}
		return {
			hitRegistered: true,
			isNewExplosion: false,
			hits: this.hits
		};
	}
	originalMaterials = /* @__PURE__ */ new Map();
	setGraphicsMode(mode) {
		const isLow = mode === "low";
		this.root.traverse((obj) => {
			if (obj instanceof Mesh) {
				obj.castShadow = !isLow;
				obj.receiveShadow = !isLow;
				if (isLow) {
					if (!this.originalMaterials.has(obj)) this.originalMaterials.set(obj, obj.material);
					const stdMat = this.originalMaterials.get(obj);
					if (stdMat && stdMat.color) obj.material = new MeshBasicMaterial({ color: stdMat.color });
				} else if (this.originalMaterials.has(obj)) obj.material = this.originalMaterials.get(obj);
			}
		});
	}
	dispose() {
		this.scene.remove(this.root);
		this.root.traverse((obj) => {
			if (obj instanceof Mesh) {
				obj.geometry.dispose();
				if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose());
				else obj.material.dispose();
			}
		});
	}
};
