			const y = .08 + this.loopRadius * (1 - Math.cos(theta));
			const z = this.loopStartZ + u * this.loopZLength;
			const dy = 2 * Math.PI * this.loopRadius * Math.sin(theta);
			const dz = this.loopZLength;
			const len = Math.hypot(dy, dz) || 1;
			const ny = dz / len;
			const nz = -dy / len;
