		this.stageMeshes.push(mesh1);
		const pointsStage2 = [
			new Vector3(120, .05, 144),
			new Vector3(138, .05, 144),
			new Vector3(144, .05, 136),
			new Vector3(144, .05, -40),
			new Vector3(136, .05, -48),
			new Vector3(0, .05, -48)
		];
		const mesh2 = this.createRoadRibbon(pointsStage2, 2.2, 24);
		this.guideLineGroup.add(mesh2);
		this.stageMeshes.push(mesh2);
		const pointsStage3 = [
			new Vector3(0, .05, -48),
			new Vector3(-40, .05, -48),
			new Vector3(-48, .05, -40),
			new Vector3(-48, .05, 40),
			new Vector3(-40, .05, 48),
			new Vector3(0, .05, 48)
		];
		const mesh3 = this.createRoadRibbon(pointsStage3, 2.2, 16);
