function createProceduralSparkTexture() {
	const canvas = document.createElement("canvas");
	canvas.width = 64;
	canvas.height = 64;
	const ctx = canvas.getContext("2d");
	const grad = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
	grad.addColorStop(0, "rgba(255, 255, 255, 1.0)");
	grad.addColorStop(.25, "rgba(255, 200, 80, 0.9)");
	grad.addColorStop(.65, "rgba(255, 80, 0, 0.4)");
	grad.addColorStop(1, "rgba(0, 0, 0, 0)");
	ctx.fillStyle = grad;
	ctx.fillRect(0, 0, 64, 64);
	const tex = new CanvasTexture(canvas);
	tex.colorSpace = SRGBColorSpace;
	return tex;
}
function createProceduralSmokeTexture() {
	const canvas = document.createElement("canvas");
	canvas.width = 64;
	canvas.height = 64;
	const ctx = canvas.getContext("2d");
	const grad = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
	grad.addColorStop(0, "rgba(100, 100, 100, 0.8)");
	grad.addColorStop(.45, "rgba(60, 60, 60, 0.45)");
	grad.addColorStop(1, "rgba(0, 0, 0, 0)");
	ctx.fillStyle = grad;
	ctx.fillRect(0, 0, 64, 64);
	const tex = new CanvasTexture(canvas);
	tex.colorSpace = SRGBColorSpace;
	return tex;
}
function createCircularShadowTexture() {
	const canvas = document.createElement("canvas");
	canvas.width = 128;
	canvas.height = 128;
	const ctx = canvas.getContext("2d");
	const grad = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
	grad.addColorStop(0, "rgba(0, 0, 0, 0.95)");
	grad.addColorStop(.4, "rgba(15, 8, 4, 0.85)");
	grad.addColorStop(.75, "rgba(40, 12, 0, 0.4)");
	grad.addColorStop(1, "rgba(0, 0, 0, 0)");
	ctx.fillStyle = grad;
	ctx.fillRect(0, 0, 128, 128);
	const tex = new CanvasTexture(canvas);
	tex.colorSpace = SRGBColorSpace;
	return tex;
}
