				if (met.light) met.light.position.copy(met.core.position);
				const distFromFloor = met.core.position.y;
				met.burnMat.opacity = Math.max(.12, Math.min(.88, .95 - distFromFloor / 52));
				const shadowScale = Math.min(1.1, .45 + (1 - distFromFloor / 52) * .65);
				met.burnMark.scale.set(shadowScale, shadowScale, 1);
