					const sPos = met.smokePositions;
					for (let i = 0; i < met.smokeDynamics.length; i++) {
						const sd = met.smokeDynamics[i];
						sPos[i * 3] += sd.vx * dt;
						sPos[i * 3 + 1] += sd.vy * dt;
						sPos[i * 3 + 2] += sd.vz * dt;
						sd.vx *= .97;
						sd.vz *= .97;
					}
					met.smokeParticles.geometry.attributes.position.needsUpdate = true;
					const sMat = met.smokeParticles.material;
