	unlockTeleport(missionId) {
		if (!this.currentUser.unlockedTeleports.includes(missionId)) {
			this.currentUser.unlockedTeleports.push(missionId);
			this.currentUser.updatedAt = Date.now();
			if (!this.currentUser.isGuest) {
				this.currentUser.pendingSync = true;
				this.saveLocalProfile(this.currentUser);
				this.syncPendingChanges();
			} else this.saveLocalProfile(this.currentUser);
			return true;
		}
		return false;
	}
	buyTeleport(missionId, price = 250) {
		if (!this.currentUser.unlockedTeleports.includes(missionId)) return {
			success: false,
			message: "Você precisa visitar o marcador desta missão no mapa/mundo primeiro para desbloqueá-la!"
		};
		if (this.currentUser.purchasedTeleports.includes(missionId)) return {
			success: true,
			message: "Teletransporte já adquirido!"
		};
		if (this.currentUser.cash < price) return {
			success: false,
			message: `Saldo insuficiente! Necessário: $ ${price.toLocaleString("pt-BR")}. Você tem: $ ${this.currentUser.cash.toLocaleString("pt-BR")}`
		};
		this.currentUser.cash -= price;
		this.currentUser.purchasedTeleports.push(missionId);
		this.currentUser.updatedAt = Date.now();
		if (!this.currentUser.isGuest) {
			this.currentUser.pendingSync = true;
			this.saveLocalProfile(this.currentUser);
			this.syncPendingChanges();
		} else this.saveLocalProfile(this.currentUser);
		return {
			success: true,
			message: `✈️ Teletransporte adquirido por $ ${price.toLocaleString("pt-BR")}! Pronto para viajar instantaneamente.`
		};
	}
