async function triggerHapticNotification(type = "success") {
	if (Capacitor.isNativePlatform() && Capacitor.isPluginAvailable("Haptics")) try {
		const typeMap = {
			success: NotificationType.Success,
			warning: NotificationType.Warning,
			error: NotificationType.Error
		};
		await Haptics.notification({ type: typeMap[type] });
		return;
	} catch {}
	if (typeof navigator !== "undefined" && typeof navigator.vibrate === "function") try {
		navigator.vibrate(type === "success" ? [
			15,
			40,
			25
		] : [
			30,
			50,
			40
		]);
	} catch {}
}
