			if (modeAttr === "tilt") btn.textContent = this.getLangText("📱 INCLINAÇÃO (SENSOR)", "📱 TILT (SENSOR)", "📱 ГИРОСКОП (НАКЛОН)", "📱 陀螺仪倾斜");
