			if (langAttr === "pt") btn.textContent = "🇧🇷 PORTUGUÊS";
			if (langAttr === "en") btn.textContent = "🇺🇸 ENGLISH";
			if (langAttr === "ru") btn.textContent = "🇷🇺 РУССКИЙ";
			if (langAttr === "zh") btn.textContent = "🇨🇳 中文";
